export function WysiwygEditor({
  content = "{{content}}",
  pageStyle = "{{pageStyle}}",
  accent = "{{accent}}",
  showBadge = {{showBadge}},
  radius = {{radius}},
}) {
  const card = pageStyle === "card";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 380 }}>
      {showBadge && (
        <p style={{ margin: "0 0 10px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: accent }}>
          This is exactly how it will look published
        </p>
      )}
      <div style={{
        background: "#fff", overflow: "hidden", borderRadius: radius,
        borderTop: card ? "none" : `4px solid ${accent}`,
        border: card ? "1.5px solid #24143020" : "none",
        boxShadow: card ? "0 10px 26px rgba(36,20,48,.14)" : "none",
        padding: card ? 18 : "22px 20px",
      }}>
        <div contentEditable suppressContentEditableWarning role="textbox" aria-multiline="true" aria-label="Page content"
          style={{ fontSize: card ? 15 : 17, lineHeight: 1.6 }}>
          {content}
        </div>
      </div>
    </div>
  );
}
